function associationLabel(p){const v=p.cadastral_validation||{},a=p.cadastral_association||{};if(v.status==='display_review_required')return t('displayReview');if(!v.registration_allowed)return t('cadastralUnverified')+' · '+(a.status==='verified_source_attribute'?t('sourceVerified'):t('sourceUnverified'));return a.status==='verified_source_attribute'?t('sourceVerified'):a.classification==='derived'?t('derived'):t('notVerified');}
function reviewReason(p){if(p.importable)return null;const v=p.cadastral_validation||{},a=p.cadastral_association||{};let key;
 if(p.sector)return [t('rs_existing').replace('{name}',p.sector.name),t('nx_existing')];
 if(!p.geometry_valid||v.status==='geometry_invalid')key='geometry_invalid';else if(p.geometry_repaired||v.status==='display_review_required')key='display_review';else if(p.import_status==='UNSUPPORTED GEOMETRY')key='unsupported';else if(v.status==='source_conflict')key='source_conflict';else if(v.status==='spatial_candidate_only')key='spatial';else if(v.status==='boundary_review_required')key='boundary';else if(a.status!=='verified_source_attribute')key='unverified';else key='boundary';
 const overlap=v.overlap_percent==null?'—':Number(v.overlap_percent).toFixed(2)+'%';return [t('rs_'+key).replace('{overlap}',overlap),t('nx_'+key)];}
