const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function node(tag,text,parent){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.append(n);return n;}
function message(text){dom('status').textContent=text;}
function button(parent,key,fn,id){const b=node('button',t(key),parent);b.className='btn';b.type='button';if(id)b.id='fm-'+id;b.onclick=()=>Promise.resolve().then(fn).catch(error=>message(error.message));return b;}
function panel(parent,title,id){const p=node('section',undefined,parent);p.className='forest-map-panel';if(id)p.id='fm-'+id;node('h3',t(title),p);return p;}
function input(parent,key,id){const label=node('label',t(key),parent);label.htmlFor='fm-'+id;const i=node('input',undefined,parent);i.id='fm-'+id;return i;}
async function request(path,body,signal){const c=new AbortController(),abort=()=>c.abort(),timer=setTimeout(abort,35000);signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)c.abort();try{const r=await fetch(path,{credentials:'same-origin',cache:'no-store',signal:c.signal,...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?translated(data.detail):t('error')+' ('+r.status+')');return data;}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}}
